import { Effect } from "effect"

export interface Shipment {
  readonly trackingNumber: string
  readonly weightKg: number
  readonly cancelled: boolean
}

export interface ManifestRequest {
  readonly depotCode: string
  readonly shipments: ReadonlyArray<Shipment>
}

export interface Manifest {
  readonly depot: string
  readonly trackingNumbers: ReadonlyArray<string>
  readonly totalWeightKg: number
}

export function prepareManifest(request: ManifestRequest) {
  return Effect.sync((): Manifest => {
    const active = request.shipments.filter((shipment) => !shipment.cancelled)
    const totalWeightKg = active.reduce(
      (total, shipment) => total + shipment.weightKg,
      0
    )

    return {
      depot: request.depotCode.trim().toUpperCase(),
      trackingNumbers: active.map((shipment) => shipment.trackingNumber),
      totalWeightKg
    }
  })
}
